<script setup lang="ts">
import type { InstallationTransport } from '../shared/types/installation'
type PackageType = 'Игра' | 'Патч' | 'Бэкпорт' | 'DLC'
type Section = 'library' | 'console' | 'torrents' | 'search' | 'log' | 'remote' | 'ftp' | 'system' | 'donate'
const SECTIONS: Section[] = ['library', 'console', 'torrents', 'search', 'log', 'remote', 'ftp', 'system', 'donate']
const donationBtc = String(useRuntimeConfig().public.donation?.btc || '').trim()
type PackageState = 'ready' | 'sending' | 'queued' | 'receiving' | 'installing' | 'delivered' | 'installed' | 'skipped' | 'failed'
interface ServerPackage { id: string; title: string; size: number; iconSize?: number; type: PackageType; titleId: string; installOrder: number; url: string; contentId: string; contentType: string; libraryRoot: string; installedAt?: number }
interface PackageItem extends ServerPackage { rowId: string; state: PackageState; detail: string; bytesSent: number; completedAt?: number; iconUrl?: string }
interface GameGroup { id: string; title: string; items: PackageItem[]; cover?: string }
interface TorrentItem { hash: string; name: string; state: string; size: number; progress: number; downloaded: number; speed: number; eta: number; seeds: number; autoInstall: boolean }
interface TorrentFile { index: number; name: string; size: number; progress: number; priority: number }
interface QbitStatus { baseUrl: string; username: string; downloadPath: string; remotePath?: string; hasPassword?: boolean; configured: boolean; ready: boolean; version: string }
interface SearchSettings { name: string; endpoint: string; configured: boolean }
interface SearchResult { title: string; source: string; size: number; seeders?: number; published?: string }
interface InstallationQueueItem { packageId: string; state: 'pending' | 'sending' | 'waiting' | 'receiving' | 'installing' | 'verifying' | 'delivered' | 'installed' | 'unconfirmed' | 'failed' | 'cancelled'; detail: string; bytesSent: number; completedAt?: number; installedAt?: number }
interface InstallationQueue { status: 'idle' | 'running' | 'cancelling' | 'completed' | 'failed' | 'cancelled'; transport?: InstallationTransport; items: InstallationQueueItem[]; message?: string }

const psIp = ref('10.1.200.5')
const activeSection = ref<Section>('library')
const connected = ref(false)
const showIpEditor = ref(false)
const statusMessage = ref('Проверяем PyLoader на PlayStation…')
const packages = ref<PackageItem[]>([])
const selected = ref(new Set<string>())
const reinstallTarget = ref<PackageItem | null>(null)
const expanded = ref(new Set<string>())
const isSending = ref(false)
const installationMethod = ref<InstallationTransport>('payload')
const queueMethod = ref<InstallationTransport>('payload')
const serviceConnected = ref(false)
const consoleConnected = ref(false)
const installationConnected = computed(() => activeSection.value === 'console' ? consoleConnected.value : installationMethod.value === 'service' ? serviceConnected.value : connected.value)
const deliveryTimers = new Map<string, number>()
const qbit = ref<QbitStatus>({ baseUrl: 'http://127.0.0.1:8080', username: '', downloadPath: '', configured: false, ready: false, version: '' })
const torrents = ref<TorrentItem[]>([])
const torrentSource = ref('')
const installAfterDownload = ref(false)
const showTorrentSettings = ref(false)
const torrentSettings = reactive({ baseUrl: 'http://127.0.0.1:8080', username: '', password: '', downloadPath: '', remotePath: '' })
const torrentFiles = ref<Record<string, TorrentFile[]>>({})
const searchSettings = reactive({ name: 'Torznab', endpoint: '', apiKey: '' })
const searchConfigured = ref(false)
const searchQuery = ref('')
const searchResults = ref<SearchResult[]>([])
const showSearchSettings = ref(false)
const searchBusy = ref(false)
let torrentTimer: number | undefined
interface LogEntry { id: number; time: number; level: 'info' | 'warn' | 'error'; text: string; count: number }
const logEntries = ref<LogEntry[]>([])
const logBox = ref<HTMLElement>()
let logLastId = 0
let logTimer: number | undefined
const activeTorrents = computed(() => torrents.value.filter((torrent) => torrent.progress < 1).length)
const logProblems = computed(() => logEntries.value.filter((entry) => entry.level !== 'info').length)
let installationTimer: number | undefined
let torrentRefreshRunning = false
const totalSize = computed(() => formatBytes(packages.value.reduce((sum, item) => sum + item.size, 0)))
const deliveredCount = computed(() => packages.value.filter((item) => item.state === 'delivered').length)
const installedCount = computed(() => packages.value.filter((item) => item.state === 'installed').length)
const selectedItems = computed(() => packages.value.filter((item) => selected.value.has(item.rowId)))
const groups = computed<GameGroup[]>(() => {
  const byTitle = new Map<string, PackageItem[]>()
  for (const item of packages.value) byTitle.set(item.titleId, [...(byTitle.get(item.titleId) || []), item])
  return [...byTitle.entries()].map(([id, items]) => {
    items.sort((a, b) => a.installOrder - b.installOrder || a.title.localeCompare(b.title))
    const game = items.find((item) => item.type === 'Игра')
    return { id, title: game?.title || `Игра ${id}`, items, cover: game?.iconUrl || items.find((item) => item.iconUrl)?.iconUrl }
  }).sort((a, b) => a.title.localeCompare(b.title))
})

/** qBittorrent < 5.0 reports pausedDL/pausedUP, 5.0+ reports stoppedDL/stoppedUP. */
function isTorrentStopped(torrent: TorrentItem) { return /paused|stopped/i.test(torrent.state) }
function logTime(time: number) { return new Date(time).toLocaleTimeString('ru-RU') }
async function refreshLog() {
  try {
    const result = await $fetch<{ entries: LogEntry[]; lastId: number }>('/api/logs', { query: { after: logLastId } })
    if (result.lastId < logLastId) { logEntries.value = []; logLastId = 0; return refreshLog() } // server restarted
    if (!result.entries.length) return
    const box = logBox.value
    const atBottom = !box || box.scrollHeight - box.scrollTop - box.clientHeight < 40
    const next = [...logEntries.value]
    for (const entry of result.entries) {
      // A repeated event comes back with a higher count: replace the previous line.
      const last = next.at(-1)
      if (entry.count > 1 && last && last.text === entry.text && last.level === entry.level) next.pop()
      next.push(entry)
    }
    logEntries.value = next.slice(-200)
    logLastId = result.lastId
    if (atBottom) await nextTick(() => { if (logBox.value) logBox.value.scrollTop = logBox.value.scrollHeight })
  } catch { /* the log is best-effort */ }
}
async function clearLog() { try { await $fetch('/api/logs', { method: 'DELETE' }); logEntries.value = [] } catch { /* ignore */ } }
/** Server errors carry their (Russian) text in `message`; `statusMessage` is kept ASCII-only by h3. */
function errorText(error: any): string | undefined { return error?.data?.message || error?.data?.statusMessage || undefined }
function formatBytes(value: number) { if (!value) return '0 Б'; const units = ['Б', 'КБ', 'МБ', 'ГБ', 'ТБ']; const index = Math.min(Math.floor(Math.log(value) / Math.log(1024)), units.length - 1); return `${(value / 1024 ** index).toFixed(index >= 3 ? 1 : 0)} ${units[index]}` }
function typeClass(type: PackageType) { return ({ Игра: 'game', Патч: 'patch', Бэкпорт: 'backport', DLC: 'dlc' })[type] }
function iconFor(item: ServerPackage) { return item.iconSize ? `/api/packages/${item.id}?asset=icon` : undefined }
function isOpen(id: string) { return expanded.value.has(id) }
function toggleGroup(id: string) { const next = new Set(expanded.value); next.has(id) ? next.delete(id) : next.add(id); expanded.value = next }
function isSelected(id: string) { return selected.value.has(id) }
function toggleSelected(id: string) { const next = new Set(selected.value); next.has(id) ? next.delete(id) : next.add(id); selected.value = next }
function setGroupSelected(group: GameGroup, checked: boolean) { const next = new Set(selected.value); group.items.forEach((item) => checked ? next.add(item.rowId) : next.delete(item.rowId)); selected.value = next }
async function connect() { showIpEditor.value = false; statusMessage.value = 'Проверяем PyLoader на порту 9090…'; try { const result = await $fetch<{ ready: boolean }>('/api/ps4/status', { method: 'POST', body: { ip: psIp.value } }); connected.value = result.ready; statusMessage.value = result.ready ? 'PyLoader готов к работе на PlayStation 4' : 'PyLoader не ответил на порту 9090' } catch (error: any) { connected.value = false; statusMessage.value = errorText(error) || 'Не удалось проверить соединение с консолью' } }
function appendPackages(items: ServerPackage[]) { const additions = items.filter((item) => !packages.value.some((existing) => existing.id === item.id)).map((item) => ({ ...item, rowId: `${Date.now()}-${Math.random().toString(36).slice(2)}`, state: item.installedAt ? 'installed' as const : 'ready' as const, detail: item.installedAt ? 'Отмечен как установленный' : 'Готов к отправке', bytesSent: 0, iconUrl: iconFor(item) })); packages.value.push(...additions); return additions }
async function scanDirectory(directory: string) { try { statusMessage.value = 'Сканируем исходные файлы — они не будут скопированы…'; const result = await $fetch<{ packages: ServerPackage[] }>('/api/packages/scan', { method: 'POST', body: { directory, psIp: psIp.value } }); const additions = appendPackages(result.packages); statusMessage.value = additions.length ? `Добавлено пакетов: ${additions.length}` : 'Подходящих .pkg или .fpkg не найдено' } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось просканировать папку' } }
async function scanServerFolder() { const directory = window.prompt('Введите полный путь к папке с .pkg/.fpkg на этом компьютере'); if (directory?.trim()) await scanDirectory(directory) }
async function chooseFolder() { try { statusMessage.value = 'Открываем системный выбор папки…'; const result = await $fetch<{ directory: string; cancelled: boolean }>('/api/packages/select-directory', { method: 'POST', body: { initial: packages.value.at(-1)?.libraryRoot } }); if (result.cancelled || !result.directory) { statusMessage.value = 'Выбор папки отменён'; return } await scanDirectory(result.directory) } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось выбрать папку' } }
async function restoreLibrary() { try { const result = await $fetch<{ packages: ServerPackage[] }>('/api/packages', { query: { psIp: psIp.value } }); const additions = appendPackages(result.packages); if (additions.length) statusMessage.value = `Восстановлено из библиотеки: ${additions.length}` } catch { /* Подключение к библиотеке будет повторено при следующем запуске. */ } }
async function refreshConsoleLibrary() {
  const result = await $fetch<{ packages: ServerPackage[] }>('/api/packages', { query: { psIp: psIp.value } })
  for (const item of packages.value) {
    const value = result.packages.find(p => p.id === item.id)
    if (value && item.installedAt && !value.installedAt) { stopDeliveryWatch(item); item.installedAt = undefined; item.state = 'ready'; item.detail = 'Удалено на PS4; пакет готов к повторной установке'; item.bytesSent = 0 }
  }
  appendPackages(result.packages)
}
function applyInstallationQueue(queue: InstallationQueue) { const states: Record<InstallationQueueItem['state'], PackageState> = { pending: 'queued', sending: 'sending', waiting: 'queued', receiving: 'receiving', installing: 'installing', verifying: 'queued', delivered: 'delivered', installed: 'installed', unconfirmed: 'skipped', failed: 'failed', cancelled: 'ready' }; for (const queued of queue.items) { const item = packages.value.find((entry) => entry.id === queued.packageId); if (!item) continue; item.state = states[queued.state]; item.detail = queued.detail; item.bytesSent = queued.bytesSent; item.completedAt = queued.completedAt; item.installedAt = queued.installedAt } isSending.value = queue.status === 'running' || queue.status === 'cancelling'; queueMethod.value = queue.transport || 'payload'; if (isSending.value) installationMethod.value = queueMethod.value; if (queue.message) statusMessage.value = queue.message }
async function restoreInstallationQueue() { try { applyInstallationQueue(await $fetch<InstallationQueue>('/api/ps4/installation')) } catch { /* Библиотека и ручная установка остаются доступны, если сервер только запускается. */ } }
async function importCompletedTorrent(item: TorrentItem) { if (item.progress < 1) return; try { const result = await $fetch<{ packages: ServerPackage[]; alreadyIndexed: boolean }>(`/api/torrents/${item.hash}/library`, { method: 'POST', body: { psIp: psIp.value } }); const additions = appendPackages(result.packages); if (additions.length) statusMessage.value = `Из torrent добавлено в библиотеку: ${additions.length} пак.`; /* Automatic installation is started by the server (torrent-autoinstall), even with this page closed. */ } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось запустить автоматическую установку torrent' } }
/** Copies the saved settings into the form. Never while the form is open, or the 2 s poll would overwrite what the user types. */
function toggleTorrentSettings() { if (!showTorrentSettings.value) syncTorrentForm(); showTorrentSettings.value = !showTorrentSettings.value }
function syncTorrentForm() { torrentSettings.baseUrl = qbit.value.baseUrl; torrentSettings.username = qbit.value.username; torrentSettings.downloadPath = qbit.value.downloadPath; torrentSettings.remotePath = qbit.value.remotePath || ''; torrentSettings.password = '' }
async function refreshTorrents() { if (torrentRefreshRunning) return; torrentRefreshRunning = true; try { qbit.value = await $fetch<QbitStatus>('/api/torrents/settings'); if (!showTorrentSettings.value) syncTorrentForm(); if (qbit.value.ready) { torrents.value = await $fetch<TorrentItem[]>('/api/torrents'); for (const item of torrents.value.filter((torrent) => torrent.progress >= 1)) await importCompletedTorrent(item) } else torrents.value = [] } catch { qbit.value.ready = false; torrents.value = [] } finally { torrentRefreshRunning = false } }
async function saveTorrentSettings() { try { qbit.value = await $fetch<QbitStatus>('/api/torrents/settings', { method: 'POST', body: torrentSettings }); showTorrentSettings.value = false; await refreshTorrents(); statusMessage.value = `qBittorrent подключён${qbit.value.version ? `: ${qbit.value.version}` : ''}` } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось подключиться к qBittorrent' } }
async function addTorrent() { if (!torrentSource.value.trim()) return; try { await $fetch('/api/torrents/add', { method: 'POST', body: { source: torrentSource.value, installAfterDownload: installAfterDownload.value } }); torrentSource.value = ''; statusMessage.value = installAfterDownload.value ? 'Torrent добавлен: после загрузки начнётся установка на PS4' : 'Торрент передан qBittorrent'; await refreshTorrents() } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось добавить торрент' } }
async function controlTorrent(item: TorrentItem, action: 'pause' | 'resume' | 'delete') { try { await $fetch(`/api/torrents/${item.hash}/${action}`, { method: 'POST' }); await refreshTorrents() } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось изменить торрент-задачу' } }
async function setTorrentAutoInstall(item: TorrentItem, enabled: boolean) { try { await $fetch(`/api/torrents/${item.hash}/auto-install`, { method: 'POST', body: { enabled } }); await refreshTorrents(); if (enabled && item.progress >= 1) statusMessage.value = 'Автоустановка включена: добавляем завершённый torrent в очередь…' } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось изменить автоустановку torrent' } }
async function loadSearchSettings() { try { const data = await $fetch<SearchSettings>('/api/search/settings'); searchSettings.name = data.name; searchSettings.endpoint = data.endpoint; searchConfigured.value = data.configured } catch { searchConfigured.value = false } }
async function saveSearchSettings() { try { const data = await $fetch<SearchSettings>('/api/search/settings', { method: 'POST', body: searchSettings }); searchSettings.name = data.name; searchSettings.endpoint = data.endpoint; searchConfigured.value = data.configured; showSearchSettings.value = false; statusMessage.value = 'Источник поиска сохранён' } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось сохранить источник поиска' } }
async function searchTorrents() { if (!searchQuery.value.trim()) return; searchBusy.value = true; try { searchResults.value = await $fetch<SearchResult[]>('/api/search', { query: { q: searchQuery.value } }); statusMessage.value = searchResults.value.length ? `Найдено результатов: ${searchResults.value.length}` : 'По запросу ничего не найдено' } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось выполнить поиск' } finally { searchBusy.value = false } }
async function downloadSearchResult(result: SearchResult) { try { await $fetch('/api/torrents/add', { method: 'POST', body: { source: result.source, installAfterDownload: installAfterDownload.value } }); statusMessage.value = 'Результат передан qBittorrent'; await refreshTorrents() } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось добавить результат в загрузки' } }
async function toggleTorrentFiles(item: TorrentItem) { if (torrentFiles.value[item.hash]) { const next = { ...torrentFiles.value }; delete next[item.hash]; torrentFiles.value = next; return } try { torrentFiles.value = { ...torrentFiles.value, [item.hash]: await $fetch<TorrentFile[]>(`/api/torrents/${item.hash}/files`) } } catch (error: any) { statusMessage.value = errorText(error) || 'Файлы станут доступны после получения metadata torrent' } }
async function setTorrentFile(item: TorrentItem, file: TorrentFile, selected: boolean) { try { await $fetch(`/api/torrents/${item.hash}/files`, { method: 'POST', body: { ids: [file.index], priority: selected ? 1 : 0 } }); torrentFiles.value = { ...torrentFiles.value, [item.hash]: await $fetch<TorrentFile[]>(`/api/torrents/${item.hash}/files`) } } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось изменить выбор файлов' } }
async function dispatchPackage(item: PackageItem) { await $fetch('/api/ps4/queue', { method: 'POST', body: { url: item.url, title: item.title, contentId: item.contentId, contentType: item.contentType, size: item.size, packageId: item.id } }) }
function stopDeliveryWatch(item: PackageItem) { const timer = deliveryTimers.get(item.rowId); if (timer) window.clearInterval(timer); deliveryTimers.delete(item.rowId) }
async function checkDelivery(item: PackageItem) { if (item.state === 'failed' || item.state === 'delivered') { stopDeliveryWatch(item); return item.state === 'delivered' } try { const data = await $fetch<{ bytesSent: number; size: number; completedAt?: number }>(`/api/packages/${item.id}?asset=delivery`); item.bytesSent = Math.min(data.bytesSent, data.size); if (data.completedAt) { item.completedAt = data.completedAt; item.state = 'delivered'; item.detail = 'Файл полностью передан PlayStation; можно передавать следующий пакет'; stopDeliveryWatch(item); return true } if (data.bytesSent > 0) { item.state = 'receiving'; item.detail = `PS4 получила ${formatBytes(item.bytesSent)} из ${formatBytes(data.size)}` } } catch { /* Не подменяем статус догадкой после перезапуска сервера. */ } return false }
function startDeliveryWatch(item: PackageItem) { stopDeliveryWatch(item); void checkDelivery(item); deliveryTimers.set(item.rowId, window.setInterval(() => void checkDelivery(item), 1500)) }
function ordered(items: PackageItem[]) { return [...items].filter((item) => item.state === 'ready').sort((a, b) => a.installOrder - b.installOrder || a.title.localeCompare(b.title)) }
async function installItems(items: PackageItem[]) {
  const queue = ordered(items)
  if (!queue.length) { statusMessage.value = 'Нет готовых выбранных пакетов'; return }
  if (installationMethod.value === 'payload') {
    if (!connected.value) await connect()
    if (!connected.value) { showIpEditor.value = true; return }
  } else {
    try {
      const status = await $fetch<{ ready: boolean; message: string }>('/api/ps4/service-installer', { query: { ip: psIp.value } })
      if (!status.ready) { statusMessage.value = status.message; return }
    } catch (error: any) { statusMessage.value = errorText(error) || 'Сервис недоступен'; return }
  }
  try {
    const packageUrls = Object.fromEntries(queue.map(item => [item.id, item.url]))
    applyInstallationQueue(await $fetch<InstallationQueue>('/api/ps4/installation', { method: 'POST', body: { ip: psIp.value, packageIds: queue.map(item => item.id), packageUrls, transport: installationMethod.value } }))
  } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось передать очередь установщику' }
}
function installOne(item: PackageItem) { return installItems([item]) }
function installDlc(group?: GameGroup) { return installItems((group?.items || packages.value).filter((item) => item.type === 'DLC')) }
async function toggleInstalled(item: PackageItem) { if (item.state !== 'ready') return resetPackage(item); try { await $fetch(`/api/packages/${item.id}/installed`, { method: 'POST', body: { installed: true } }); stopDeliveryWatch(item); item.installedAt = Date.now(); item.state = 'installed'; item.detail = 'Отмечен как установленный' } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось изменить отметку установки' } }
async function resetPackage(item: PackageItem) { try { await $fetch(`/api/packages/${item.id}/reset`, { method: 'POST' }); stopDeliveryWatch(item); item.installedAt = undefined; item.completedAt = undefined; item.bytesSent = 0; item.state = 'ready'; item.detail = 'Готов к отправке'; statusMessage.value = `«${item.title}» можно установить заново` } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось сбросить статус пакета' } }
const isCancelling = ref(false)
async function cancelInstallation() { if (!window.confirm(queueMethod.value === 'service' ? 'Запросить отмену задания на PS4? WEB дождётся ответа консоли; следующие пакеты не будут отправлены.' : 'Отменить установку? Текущая передача на PS4 будет прервана, оставшиеся пакеты не будут отправлены.')) return; isCancelling.value = true; try { applyInstallationQueue(await $fetch<InstallationQueue>('/api/ps4/installation/cancel', { method: 'POST' })) } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось отменить установку' } finally { isCancelling.value = false } }
async function removePackage(item: PackageItem) { if (!window.confirm(`Убрать «${item.title}» из библиотеки? Исходный PKG останется на диске.`)) return; try { await $fetch(`/api/packages/${item.id}`, { method: 'DELETE' }); stopDeliveryWatch(item); packages.value = packages.value.filter((entry) => entry.rowId !== item.rowId); const next = new Set(selected.value); next.delete(item.rowId); selected.value = next; statusMessage.value = 'Пакет удалён из списка. Исходный файл не изменён.' } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось удалить пакет из списка' } }
async function reindexBranch(group: GameGroup) { const root = group.items[0]?.libraryRoot; if (!root) { statusMessage.value = 'Не найден исходный путь ветки. Просканируйте папку заново.'; return } try { statusMessage.value = `Переиндексируем ${group.id}…`; const result = await $fetch<{ packages: ServerPackage[] }>('/api/packages/scan', { method: 'POST', body: { directory: root, psIp: psIp.value, titleId: group.id } }); group.items.forEach(stopDeliveryWatch); const removedIds = new Set(group.items.map((item) => item.rowId)); packages.value = packages.value.filter((item) => !removedIds.has(item.rowId)); const next = new Set(selected.value); removedIds.forEach((id) => next.delete(id)); selected.value = next; const additions = appendPackages(result.packages); statusMessage.value = `Ветка переиндексирована: ${additions.length} пак.` } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось переиндексировать ветку' } }
async function removeBranch(group: GameGroup) { if (!window.confirm(`Убрать всю ветку ${group.id}: игру, патчи и DLC? Исходные PKG останутся на диске.`)) return; try { await $fetch('/api/packages/branch', { method: 'DELETE', query: { titleId: group.id } }); group.items.forEach(stopDeliveryWatch); const ids = new Set(group.items.map((item) => item.rowId)); packages.value = packages.value.filter((item) => !ids.has(item.rowId)); const next = new Set(selected.value); ids.forEach((id) => next.delete(id)); selected.value = next; statusMessage.value = `Ветка ${group.id} удалена из библиотеки` } catch (error: any) { statusMessage.value = errorText(error) || 'Не удалось удалить ветку' } }
onBeforeUnmount(() => { deliveryTimers.forEach((timer) => window.clearInterval(timer)); if (torrentTimer) window.clearInterval(torrentTimer); if (installationTimer) window.clearInterval(installationTimer); if (logTimer) window.clearInterval(logTimer) })
async function restorePsIp() { try { const saved = await $fetch<{ ip: string }>('/api/ps4/settings'); if (saved.ip) { psIp.value = saved.ip; return true } } catch { /* Сервер ещё запускается — останется адрес по умолчанию. */ } return false }
// The open section lives in the URL hash (#torrents, #log…) so a reload keeps it.
function sectionFromHash() { const name = window.location.hash.slice(1) as Section; return SECTIONS.includes(name) && (name !== 'donate' || donationBtc) ? name : 'library' }
watch(activeSection, (section) => { const hash = section === 'library' ? '' : `#${section}`; if (window.location.hash !== hash) history.replaceState(null, '', `${window.location.pathname}${window.location.search}${hash}`); if (section === 'log') void nextTick(() => { if (logBox.value) logBox.value.scrollTop = logBox.value.scrollHeight }) })
onMounted(() => { activeSection.value = sectionFromHash(); window.addEventListener('hashchange', () => { activeSection.value = sectionFromHash() }) })
onMounted(() => { void restorePsIp().then((restored) => { if (restored) return connect(); showIpEditor.value = true; statusMessage.value = 'Укажите IP-адрес PlayStation и нажмите «Подключить»' }).then(() => restoreLibrary()).then(restoreInstallationQueue);  void refreshTorrents(); void loadSearchSettings(); torrentTimer = window.setInterval(() => { if (document.visibilityState === 'visible') void refreshTorrents() }, 2000); installationTimer = window.setInterval(() => { if (document.visibilityState === 'visible') void restoreInstallationQueue() }, 1500); void refreshLog(); logTimer = window.setInterval(() => { if (document.visibilityState === 'visible') void refreshLog() }, 2000) })
</script>

<template>
  <main class="shell"><header class="topbar"><div class="brand"><span class="brand-mark">P</span>Package<em>Flow</em></div><div class="connection"><span class="status-dot" :class="{ offline: !installationConnected }" /><span>{{ installationConnected ? 'PS4 подключена' : 'PS4 не подключена' }}</span><button class="ip-button" @click="showIpEditor = !showIpEditor">{{ psIp }}</button><form v-if="showIpEditor" class="ip-editor" @submit.prevent="connect"><input v-model="psIp" inputmode="decimal"><button>Подключить</button></form></div></header>
    <nav class="sidebar" aria-label="Разделы PackageFlow">
      <span class="sidebar-caption">РАЗДЕЛЫ</span>
      <button :class="{ active: activeSection === 'library' }" title="Библиотека" @click="activeSection = 'library'"><span aria-hidden="true">▦</span><span class="nav-label">Библиотека</span><small v-if="isSending" class="nav-badge live" title="Идёт установка">●</small></button><button :class="{ active: activeSection === 'console' }" title="На консоли" @click="activeSection = 'console'"><span aria-hidden="true">▣</span><span class="nav-label">На консоли</span></button><button :class="{ active: activeSection === 'torrents' }" title="Загрузки torrent" @click="activeSection = 'torrents'"><span aria-hidden="true">⇣</span><span class="nav-label">Загрузки</span><small v-if="activeTorrents" class="nav-badge">{{ activeTorrents }}</small></button><button :class="{ active: activeSection === 'search' }" title="Поиск torrent" @click="activeSection = 'search'"><span aria-hidden="true">⌕</span><span class="nav-label">Поиск</span></button><button :class="{ active: activeSection === 'log' }" title="Журнал" @click="activeSection = 'log'"><span aria-hidden="true">☰</span><span class="nav-label">Журнал</span><small v-if="logProblems" class="nav-badge warn">{{ logProblems }}</small></button>
      <button :class="{ active: activeSection === 'remote' }" title="Удалённый доступ" @click="activeSection = 'remote'"><span aria-hidden="true">▣</span><span class="nav-label">Удалённый доступ</span></button>
      <button :class="{ active: activeSection === 'ftp' }" title="FTP" @click="activeSection = 'ftp'"><span aria-hidden="true">⇅</span><span class="nav-label">FTP</span></button>
      <button :class="{ active: activeSection === 'system' }" title="О системе" @click="activeSection = 'system'"><span aria-hidden="true">ⓘ</span><span class="nav-label">О системе</span></button>
      <button v-if="donationBtc" class="donate-link" :class="{ active: activeSection === 'donate' }" title="Поддержать проект" @click="activeSection = 'donate'"><span aria-hidden="true">♥</span><span class="nav-label">Поддержать</span></button><span class="sidebar-note">PS4 {{ psIp }}</span>
    </nav>
    <section v-show="activeSection === 'library'" class="content"><div class="intro"><div><p class="eyebrow">ЛОКАЛЬНАЯ БИБЛИОТЕКА</p><h1>Игры и дополнения</h1><p>Пакеты автоматически объединяются по CUSA. Исходные файлы остаются в выбранной папке.</p></div><div class="pickers"><button class="primary" @click="chooseFolder">Выбрать папку</button></div></div>
      <section class="stats"><article><span>ИГРЫ</span><strong>{{ groups.length }}</strong><small>{{ packages.length }} пакетов</small></article><article><span>ВЫБРАНО</span><strong>{{ selectedItems.length }}</strong><small>{{ formatBytes(selectedItems.reduce((sum, item) => sum + item.size, 0)) }}</small></article><article><span>ПЕРЕДАНО PS4</span><strong>{{ deliveredCount }}</strong><small>из {{ packages.length }} пакетов</small></article><article><span>УСТАНОВЛЕНО</span><strong>{{ installedCount }}</strong><small>подтверждено или отмечено вручную</small></article></section>
      <ReinstallGame :ip="psIp" :pkg="reinstallTarget" @close="reinstallTarget = null" @changed="refreshConsoleLibrary" /><InstallationMethod v-model="installationMethod" :ip="psIp" :disabled="isSending" @status="serviceConnected = $event" />
      <section class="library"><div class="library-head"><div><h2>Очередь установки</h2><p>{{ statusMessage }}</p></div><div class="actions"><button class="secondary" :disabled="isSending || !selectedItems.length" @click="installItems(selectedItems)">Установить выбранное</button><button class="secondary" :disabled="isSending || !packages.some((item) => item.type === 'DLC' && item.state === 'ready')" @click="installDlc()">Все DLC</button><button v-if="isSending" class="danger" :disabled="isCancelling" @click="cancelInstallation">{{ isCancelling ? 'Отменяем…' : 'Отменить установку' }}</button><button class="primary" :disabled="isSending || !packages.length" @click="installItems(packages)">{{ isSending ? 'Передаём…' : 'Установить всё' }}</button></div></div><p v-if="!groups.length" class="empty">Выберите файлы или папку. Для пути на ПК можно использовать «Сканировать путь» ниже.</p>
        <article v-for="group in groups" :key="group.id" class="game-group"><div class="game-head"><button class="expand" @click="toggleGroup(group.id)"><span :class="{ open: isOpen(group.id) }">›</span></button><div class="game-cover"><img v-if="group.cover" :src="group.cover" alt=""><span v-else>{{ group.title.charAt(0) }}</span></div><button class="game-name" @click="toggleGroup(group.id)"><strong>{{ group.title }}</strong><span>{{ group.id }} · {{ group.items.length }} пак.</span></button><div class="group-actions"><label class="select-all"><input type="checkbox" :checked="group.items.every((item) => isSelected(item.rowId))" @change="setGroupSelected(group, ($event.target as HTMLInputElement).checked)"> все</label><button class="tiny" :disabled="isSending || !group.items.some((item) => item.type === 'DLC' && item.state === 'ready')" @click="installDlc(group)">DLC</button><button class="tiny" :disabled="isSending" @click="reindexBranch(group)">Переиндекс.</button><button class="tiny" :disabled="isSending" @click="removeBranch(group)">Удалить ветку</button></div></div>
          <div v-show="isOpen(group.id)" class="package-list"><div v-for="item in group.items" :key="item.rowId" class="package-row"><input type="checkbox" :checked="isSelected(item.rowId)" @change="toggleSelected(item.rowId)"><div class="cover"><img v-if="item.iconUrl" :src="item.iconUrl" alt=""><span v-else>{{ item.type === 'Игра' ? item.title.charAt(0) : item.type }}</span></div><div class="package-name"><strong>{{ item.title }}</strong><span>{{ item.contentId }}</span><div v-if="item.state === 'receiving' || item.state === 'installing' || item.state === 'delivered'" class="progress"><i :style="{ width: `${Math.min(100, item.bytesSent / item.size * 100)}%` }" /></div></div><span class="type" :class="typeClass(item.type)">{{ item.type }}</span><span class="size">{{ formatBytes(item.size) }}</span><span class="state" :class="item.state">{{ item.detail }}</span><button class="tiny install-one" :disabled="isSending || item.state !== 'ready'" @click="installOne(item)">Установить</button><button v-if="item.contentType === 'PS4GD'" class="tiny" :disabled="isSending" @click="reinstallTarget = item">Переустановить</button><button class="tiny mark" :class="{ reset: item.state !== 'ready' }" :disabled="isSending && item.state !== 'ready' && item.state !== 'installed' && item.state !== 'delivered' && item.state !== 'failed'" :title="item.state === 'ready' ? 'Отметить как уже установленный' : 'Сбросить статус, чтобы установить заново'" @click="toggleInstalled(item)">{{ item.state === 'ready' ? 'Установлено' : 'Сбросить' }}</button><button class="remove" title="Убрать из списка" @click="removePackage(item)">×</button></div></div></article>
      </section><section class="path-card"><div><strong>Сканировать путь на ПК</strong><p>Альтернатива системному выбору папки. PKG никогда не копируются во временный кэш.</p></div><button class="secondary" @click="scanServerFolder">Указать путь</button></section><p class="notice">Статус «файл полностью передан» подтверждается по HTTP-раздаче пакета. PyLoader не возвращает финальный результат установки. PackegeFlowService дополнительно сообщает состояние системного задания и подтверждение установки.</p></section>
    <section v-show="activeSection === 'torrents'" class="content tool-page"><p class="eyebrow">QBITTORRENT</p><h1>Загрузки torrent</h1><p class="page-status">{{ statusMessage }}</p><section class="torrent-card"><div class="torrent-head"><div><h2>Загрузки torrent</h2><p>{{ qbit.ready ? `qBittorrent подключён${qbit.version ? ` · ${qbit.version}` : ''}` : 'Подключите qBittorrent Web UI (на этом ПК или в локальной сети), чтобы добавить разрешённую magnet- или .torrent-ссылку.' }}</p></div><div class="actions"><button class="secondary" @click="refreshTorrents">Обновить</button><button class="secondary" @click="toggleTorrentSettings">Настроить</button></div></div><form v-if="showTorrentSettings" class="torrent-settings" @submit.prevent="saveTorrentSettings"><label class="wide"><span>Адрес qBittorrent Web UI — этот ПК, NAS или другой компьютер в сети</span><input v-model="torrentSettings.baseUrl" placeholder="http://192.168.1.10:8080"></label><label><span>Логин</span><input v-model="torrentSettings.username" placeholder="admin" autocomplete="username"></label><label><span>Пароль</span><input v-model="torrentSettings.password" type="password" :placeholder="qbit.hasPassword ? 'пусто — оставить сохранённый' : ''" autocomplete="current-password"></label><label><span>Папка загрузок на этом ПК — отсюда PackageFlow берёт PKG</span><input v-model="torrentSettings.downloadPath" placeholder="D:\Torrents или /home/user/Downloads"></label><label><span>Та же папка в qBittorrent — если он на другом компьютере (необязательно)</span><input v-model="torrentSettings.remotePath" placeholder="/downloads"></label><div class="wide"><button class="primary">Сохранить и проверить</button></div></form><form class="torrent-add" @submit.prevent="addTorrent"><input v-model="torrentSource" :disabled="!qbit.ready" placeholder="Вставьте разрешённую magnet- или HTTPS .torrent-ссылку"><label class="torrent-auto"><input v-model="installAfterDownload" type="checkbox" :disabled="!qbit.ready"> Установить после загрузки</label><button class="primary" :disabled="!qbit.ready || !torrentSource.trim()">Скачать</button></form><p v-if="!torrents.length && qbit.ready" class="empty">Нет torrent-задач PackageFlow.</p><div v-for="torrent in torrents" :key="torrent.hash" class="torrent-row"><div class="torrent-name"><strong>{{ torrent.name }}</strong><span>{{ formatBytes(torrent.downloaded) }} из {{ formatBytes(torrent.size) }} · {{ torrent.seeds }} сидов · {{ formatBytes(torrent.speed) }}/с</span><div class="progress"><i :style="{ width: `${Math.round(torrent.progress * 100)}%` }" /></div></div><span class="torrent-percent">{{ Math.round(torrent.progress * 100) }}%</span><label class="torrent-auto"><input type="checkbox" :checked="torrent.autoInstall" @change="setTorrentAutoInstall(torrent, ($event.target as HTMLInputElement).checked)"> Автоустановка</label><button class="tiny" @click="toggleTorrentFiles(torrent)">{{ torrentFiles[torrent.hash] ? 'Скрыть файлы' : 'Файлы' }}</button><button class="tiny" @click="controlTorrent(torrent, isTorrentStopped(torrent) ? 'resume' : 'pause')">{{ isTorrentStopped(torrent) ? 'Продолжить' : 'Пауза' }}</button><button class="remove" title="Убрать задачу, не удаляя файлы" @click="controlTorrent(torrent, 'delete')">×</button><div v-if="torrentFiles[torrent.hash]" class="torrent-files"><label v-for="file in torrentFiles[torrent.hash]" :key="file.index"><input type="checkbox" :checked="file.priority > 0" @change="setTorrentFile(torrent, file, ($event.target as HTMLInputElement).checked)"><span>{{ file.name }}</span><small>{{ formatBytes(file.size) }} · {{ Math.round(file.progress * 100) }}%</small></label></div></div></section></section><section v-show="activeSection === 'search'" class="content tool-page"><p class="eyebrow">TORZNAB</p><h1>Поиск torrent</h1><p class="page-status">{{ statusMessage }}</p><section class="search-card"><div class="search-head"><div><p class="eyebrow">РАЗРЕШЁННЫЙ ИСТОЧНИК</p><h2>Поиск torrent</h2></div><button class="secondary" @click="showSearchSettings = !showSearchSettings">Источник</button></div><form v-if="showSearchSettings" class="search-settings" @submit.prevent="saveSearchSettings"><input v-model="searchSettings.name" placeholder="Название источника"><input v-model="searchSettings.endpoint" placeholder="URL Torznab API"><input v-model="searchSettings.apiKey" type="password" placeholder="API‑ключ (если нужен)"><button class="primary">Сохранить</button></form><form class="search-form" @submit.prevent="searchTorrents"><input v-model="searchQuery" :disabled="!searchConfigured" placeholder="Название пакета"><button class="primary" :disabled="!searchConfigured || !searchQuery.trim() || searchBusy">{{ searchBusy ? 'Ищем…' : 'Найти' }}</button></form><p v-if="!searchConfigured" class="search-note">Добавьте разрешённый Torznab‑источник через кнопку «Источник».</p><div v-for="result in searchResults" :key="result.source" class="search-result"><div><strong>{{ result.title }}</strong><span>{{ formatBytes(result.size) }}<template v-if="result.seeders"> · {{ result.seeders }} сидов</template></span></div><button class="tiny" @click="downloadSearchResult(result)">Скачать</button></div></section></section><section v-show="activeSection === 'log'" class="content tool-page"><p class="eyebrow">СОБЫТИЯ СЕРВЕРА</p><h1>Журнал</h1><section class="log-card"><div class="log-head"><h2>Журнал</h2><p>События сервера: запросы PS4, передача пакетов, qBittorrent и ошибки.</p><button class="tiny" :disabled="!logEntries.length" @click="clearLog">Очистить</button></div><div ref="logBox" class="log-list"><p v-if="!logEntries.length" class="log-empty">Пока событий нет.</p><div v-for="entry in logEntries" :key="entry.id" class="log-line" :class="entry.level"><time>{{ logTime(entry.time) }}</time><span>{{ entry.text }}</span><b v-if="entry.count > 1">×{{ entry.count }}</b></div></div></section></section><section v-if="activeSection === 'remote'" class="content tool-page"><p class="eyebrow">УДАЛЁННЫЙ ДОСТУП</p><h1>Экран и настройки PS4</h1><p>Здесь появится экран консоли и управление её меню с клавиатуры и мыши после проверки Remote Play на приставке. Планируем локальное сопряжение без входа в PSN; возможность подключения проверим на вашей PS4.</p><div class="tool-card"><h2>Подготовка подключения</h2><ol><li>Включите «Дистанционную игру» в настройках PS4.</li><li>Откройте «Добавить устройство» и получите код сопряжения.</li><li>Проверьте подключение в Chiaki-ng без входа в PSN. Затем подключим браузерный клиент к этому разделу.</li></ol><p>Сервис PackegeFlowService пока проверяется отдельно через <code>GET /ping</code> на порту 12801.</p></div></section>
    <section v-if="activeSection === 'donate' && donationBtc" class="content tool-page"><DonatePanel :btc="donationBtc" /></section><section v-if="activeSection === 'ftp'" class="content tool-page"><FtpBrowser :ps-ip="psIp" /></section>
    <section v-if="activeSection === 'console'" class="content tool-page"><ConsoleApps :ip="psIp" @status="consoleConnected = $event" @changed="refreshConsoleLibrary" /></section>
    <section v-if="activeSection === 'system'" class="content tool-page"><SystemInfo :ps-ip="psIp" /></section>
  </main>
  
</template>

<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root { font-family: Manrope, Arial, sans-serif; color: #e9e8ef; background: #101012; } * { box-sizing: border-box; } body { margin: 0; min-width: 900px; background: radial-gradient(900px 600px at 90% 0, #29204155, transparent 65%), #101012; } button, input { font: inherit; } button { cursor: pointer; } button:disabled { opacity: .42; cursor: not-allowed; }.shell { min-height: 100vh; }.topbar { height: 72px; border-bottom: 1px solid #28272d; padding: 0 max(32px, calc((100vw - 1240px) / 2)); display: flex; align-items: center; justify-content: space-between; background: #151518dd; backdrop-filter: blur(10px); position: sticky; top: 0; z-index: 5; }.brand { font-size: 18px; font-weight: 800; letter-spacing: -.7px; display: flex; align-items: center; gap: 2px; }.brand em { color: #a292f3; font-style: normal; }.brand-mark { display: grid; place-items: center; width: 27px; height: 27px; margin-right: 8px; color: #16141d; background: linear-gradient(135deg, #e1dbff, #806ee0); border-radius: 8px; font-size: 15px; }.connection { position: relative; display: flex; gap: 8px; align-items: center; color: #9f9fa7; font: 11px 'DM Mono', monospace; }.status-dot { width: 7px; height: 7px; border-radius: 50%; background: #7ec78a; box-shadow: 0 0 0 3px #7ec78a1c; }.status-dot.offline { background: #dc7d72; box-shadow: none; }.ip-button { border: 0; background: #25242a; color: #dad7e8; padding: 7px 9px; border-radius: 5px; font: inherit; }.ip-editor { position: absolute; right: 0; top: 34px; padding: 9px; display: flex; gap: 6px; background: #222127; border: 1px solid #3e3b49; border-radius: 7px; box-shadow: 0 12px 30px #0007; }.ip-editor input { width: 125px; color: white; background: #121216; border: 1px solid #514a6c; border-radius: 4px; padding: 6px; }.ip-editor button, .primary { border: 0; color: white; background: #7967d3; border-radius: 6px; padding: 10px 13px; font-size: 11px; font-weight: 800; }.ip-editor button { padding: 6px; }.primary:hover { background: #8976e4; }.conten